  export interface BaseDynamicLayer extends Layer, ScaleRangeLayer, RefreshableLayer, BlendLayer {
  }

  export class BaseDynamicLayer {
    /**
     * Blend modes are used to blend layers together to create an interesting effect in a layer, or even to produce what seems like a new layer.
     *
     * @default "normal"
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#blendMode Read more...}
     */
    declare blendMode: BlendLayer["blendMode"];
    /**
     * Effect provides various filter functions that can be performed on the layer to achieve different visual effects similar to
     * how image filters work.
     *
     * @default null
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#effect Read more...}
     */
    effect: Effect | nullish;
    /**
     * The maximum scale (most zoomed in) at which the layer is visible in the view.
     *
     * @default 0
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#maxScale Read more...}
     */
    declare maxScale: ScaleRangeLayer["maxScale"];
    /**
     * The minimum scale (most zoomed out) at which the layer is visible in the view.
     *
     * @default 0
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#minScale Read more...}
     */
    declare minScale: ScaleRangeLayer["minScale"];
    /**
     * Refresh interval of the layer in minutes.
     *
     * @default 0
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#refreshInterval Read more...}
     */
    declare refreshInterval: RefreshableLayer["refreshInterval"];
    readonly type: "base-dynamic";
    /**
     * This class may be extended to create dynamic map layers.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html Read more...}
     */
    constructor(properties?: BaseDynamicLayerProperties);
    /**
     * Adds a promise to the layer's loadable chain.
     *
     * @param promiseToLoad A promise that must resolve for the layer to resolve and move from the `loading` {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#loadStatus status} to being {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#loaded loaded}.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#addResolvingPromise Read more...}
     */
    addResolvingPromise(promiseToLoad: Promise<any>): void;
    /**
     * This method fetches the image for the specified extent and size.
     *
     * @param extent The extent of the view. This value is provided by the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-layers-LayerView.html LayerView}.
     * @param width The width of the view in pixels. This value is provided by the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-layers-LayerView.html LayerView}.
     * @param height The height of the view in pixels. This value is provided by the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-layers-LayerView.html LayerView}.
     * @param options The parameter options is an object with the following properties.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#fetchImage Read more...}
     */
    fetchImage(extent: Extent, width: number, height: number, options?: BaseDynamicLayerFetchImageOptions): Promise<HTMLImageElement | HTMLCanvasElement>;
    /**
     * This method returns a URL to an image for a given extent, width, and height.
     *
     * @param extent Extent of the view. This value is populated by the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-layers-LayerView.html LayerView}.
     * @param width Width of the view in pixels. This value is populated by the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-layers-LayerView.html LayerView}.
     * @param height Height of the view in pixels. This value is populated by the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-layers-LayerView.html LayerView}.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#getImageUrl Read more...}
     */
    getImageUrl(extent: Extent, width: number, height: number): Promise<string> | string;
    /**
     * Fetches all the data for the layer.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-BaseDynamicLayer.html#refresh Read more...}
     */
    refresh(): void;
    on(name: "refresh", eventHandler: BaseDynamicLayerRefreshEventHandler): IHandle;
    on(name: "layerview-create", eventHandler: BaseDynamicLayerLayerviewCreateEventHandler): IHandle;
    on(name: "layerview-create-error", eventHandler: BaseDynamicLayerLayerviewCreateErrorEventHandler): IHandle;
    on(name: "layerview-destroy", eventHandler: BaseDynamicLayerLayerviewDestroyEventHandler): IHandle;
  }

