  /**
   * Provides the utility function to convert image coordinates to geographic coordinates.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-orientedImagery-transformations-imageToWorld.html Read more...}
   */
  interface imageToWorld {
    /**
     * Transforms image coordinates in pixels to a point or an array of points specifying the corresponding geographic world coordinates.
     *
     * @param pixelOrPixels A single `Pixel` object or an `ArrayOrCollection<Pixel>` representing the image coordinates in `x` and `y` (in rows and columns) to be transformed. Here (0, 0) corresponds to the center of the upper left pixel.
     * @param properties An object containing the properties required for the transformation, such as camera location, rotation matrix, and image dimensions.
     * @param updateElevationProps An object containing the properties required for correcting the elevation of the output point, resulting in a more accurate z-value. This is an optional parameter.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-orientedImagery-transformations-imageToWorld.html#imageToWorld Read more...}
     */
    imageToWorld(pixelOrPixels: imageToWorldPixelLocation | imageToWorldPixelLocation[], properties: ImageToWorldProperties, updateElevationProps?: UpdateElevationProps): Promise<Point | Point[]>;
  }

  export const imageToWorld: imageToWorld;

  /**
   * Represents the properties required for transforming image coordinates to world coordinates.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-orientedImagery-transformations-imageToWorld.html#ImageToWorldProperties Read more...}
   */
