  /**
   * Contains convenience methods for getting Arcade expressions defined on a layer.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-support-arcadeUtils.html Read more...}
   */
  interface arcadeUtils {
    /**
     * Returns all Arcade expressions defined on a given layer and provides metadata describing the context for which each expression was authored.
     *
     * @param layer The layer from which to get all Arcade expressions.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-support-arcadeUtils.html#getExpressionsFromLayer Read more...}
     */
    getExpressionsFromLayer(layer: | CSVLayer
      | FeatureLayer
      | GeoJSONLayer
      | Sublayer
      | OGCFeatureLayer
      | SceneLayer
      | WFSLayer
      | OrientedImageryLayer
      | CatalogFootprintLayer
      | KnowledgeGraphSublayer): arcadeUtilsExpressionInfo[];
  }

  export const arcadeUtils: arcadeUtils;

  /**
   * Represents the result of the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-support-arcadeUtils.html#getExpressionsFromLayer getExpressionsFromLayer} method.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-support-arcadeUtils.html#ExpressionInfo Read more...}
   */
  export interface arcadeUtilsExpressionInfo {
    expression: string;
    name?: string | nullish;
    title?: string | nullish;
    profileInfo: ExpressionInfoProfileInfo;
  }

  /**
   * Describes the context for which an Arcade expression was defined using the Feature Z profile.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-support-arcadeUtils.html#FeatureZProfileContext Read more...}
   */
  export type FeatureZProfileContext = "order-by" | "elevation-info";
  /**
   * Describes the context for which an Arcade expression was defined using the popup or popup element profile.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-support-arcadeUtils.html#PopupProfileContext Read more...}
   */
  export type PopupProfileContext = "popup-template" | "popup-expression-content";
  /**
   * Describes the context for which an Arcade expression was defined.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-support-arcadeUtils.html#ProfileContext Read more...}
   */
  export type ProfileContext = | VisualizationProfileContext
    | PopupProfileContext
    | FeatureZProfileContext
    | "label-class"
    | "form-template"
    | "aggregate-field";
  /**
   * Describes the context for which an Arcade expression was defined using the visualization profile.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-support-arcadeUtils.html#VisualizationProfileContext Read more...}
   */
  export type VisualizationProfileContext = | "unique-value-renderer"
    | "class-breaks-renderer"
    | "dot-density-renderer"
    | "heatmap-renderer"
    | "pie-chart-renderer"
    | "color-variable"
    | "size-variable"
    | "opacity-variable"
    | "rotation-variable";

  export interface ExpressionInfoProfileInfo {
    name: | "aggregate-field"
    | "form-constraint"
    | "feature-z"
    | "field-calculation"
    | "form-calculation"
    | "labeling"
    | "popup"
    | "popup-element"
    | "popup-feature-reduction"
    | "popup-element-feature-reduction"
    | "visualization"
    | "popup-voxel"
    | "popup-element-voxel";
    context: ProfileContext;
    source?: "layer" | "feature-reduction";
    returnType?: "boolean" | "date" | "number" | "string" | "dictionary";
  }

