  /**
   * Represents a GP resource exposed by the ArcGIS REST API.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-rest-geoprocessor.html Read more...}
   */
  interface geoprocessor {
    /**
     * Sends a request to the server to execute a synchronous GP task.
     *
     * @param url URL to the ArcGIS Server REST resource that represents a Geoprocessing service.
     * @param params
     * Specifies the input parameters accepted by the task and their corresponding values. These input parameters are listed in the parameters field of the associated GP Task resource. For example, assume that a GP Task resource has the following input parameters:
     *   * `<GPFeatureRecordSetLayer>` Input_Points
     *   * `<GPDouble>` Distance
     *
     *
     * The `params` argument would then be an Object of the form:
     * ```
     * {
     *  Input_Points: <FeatureSet>,
     *  Distance: <Number>
     * }
     *
     * ```
     * @param options
     * specifies the input options for the geoprocessing service return values. The `options` argument could be an Object of the form:
     * ```
     * {
     *   returnZ: true
     * }
     *
     * ```
     * @param requestOptions Additional {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-request.html#request options} to be used for the data request.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-rest-geoprocessor.html#execute Read more...}
     */
    execute(url: string, params?: any, options?: GPOptions, requestOptions?: RequestOptions): Promise<any>;
    /**
     * Submits a job to the server for asynchronous processing by the GP task.
     *
     * @param url URL to the ArcGIS Server REST resource that represents a Geoprocessing service.
     * @param params
     * specifies the input parameters accepted by the task and their corresponding values. These input parameters are listed in the parameters field of the associated GP Task resource. For example, assume that a GP Task resource has the following input parameters:
     *   * `<GPFeatureRecordSetLayer>` Input_Points
     *   * `<GPDouble>` Distance
     *
     *
     * The `params` argument would then be an Object of the form:
     * ```
     * {
     *   Input_Points: <FeatureSet>,
     *   Distance: <Number>
     * }
     *
     * ```
     * @param options
     * specifies the input options for the geoprocessing service return values. The `options` argument could be an Object of the form:
     * ```
     * {
     *   returnZ: true
     * }
     *
     * ```
     * @param requestOptions Additional {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-request.html#request options} to be used for the data request.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-rest-geoprocessor.html#submitJob Read more...}
     */
    submitJob(url: string, params?: any, options?: GPOptions, requestOptions?: RequestOptions): Promise<JobInfo>;
  }

