  interface SceneViewProperties extends ViewProperties, BreakpointsOwnerProperties, PopupViewProperties, DOMContainerProperties {
    /**
     * Allows the view to be partially or fully transparent when composited with the webpage elements behind it.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#alphaCompositingEnabled Read more...}
     */
    alphaCompositingEnabled?: boolean;
    /**
     * A collection of analyses associated with the view.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#analyses Read more...}
     */
    analyses?: CollectionProperties<Analysis>;
    /**
     * The ARIA attributes for the view container.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#aria Read more...}
     */
    aria?: DOMContainerProperties["aria"];
    /**
     * A convenience property used for defining the breakpoints on the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#height height}
     * and {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#width width} of the view.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#breakpoints Read more...}
     */
    breakpoints?: BreakpointsOwnerProperties["breakpoints"];
    /**
     * The observation point from which the visible portion (or perspective) of the SceneView is determined.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#camera Read more...}
     */
    camera?: CameraProperties;
    /**
     * Represents the view's center point; when setting the center you may pass a
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-geometry-Point.html Point} instance or an array of numbers representing
     * at longitude/latitude pair (`[-100.4593, 36.9014]`).
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#center Read more...}
     */
    center?: PointProperties | number[];
    /**
     * Represents an optional clipping area used to define the visible {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-geometry-Extent.html extent} of
     * a local scene.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#clippingArea Read more...}
     */
    clippingArea?: ExtentProperties | nullish;
    /**
     * Specifies constraints for [Camera tilt](esri-Camera.html#tilt) and altitude that may be applied to the SceneView.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#constraints Read more...}
     */
    constraints?: SceneViewConstraintsProperties;
    /**
     * The `id` or node representing the DOM element containing the view.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#container Read more...}
     */
    container?: HTMLDivElement | nullish | string;
    /**
     * Specifies various properties of the environment's visualization in the view.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#environment Read more...}
     */
    environment?: SceneViewEnvironmentProperties;
    /**
     * The extent represents the visible portion of a {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-Map.html map} within the view as
     * an instance of an {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-geometry-Extent.html Extent}.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#extent Read more...}
     */
    extent?: ExtentProperties;
    /**
     * Applies a display filter on the view for a specific set of floor levels.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#floors Read more...}
     */
    floors?: CollectionProperties<string>;
    /**
     * A convenience property indicating the general size of the view's height.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#heightBreakpoint Read more...}
     */
    heightBreakpoint?: BreakpointsOwnerProperties["heightBreakpoint"];
    /**
     * Options for configuring the highlight.
     *
     * @deprecated since version 4.32. Use the [highlights](#highlights) property instead.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#highlightOptions Read more...}
     */
    highlightOptions?: HighlightOptionsProperties;
    /**
     * A {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-widgets-Popup.html Popup} object that displays general content or attributes from
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-Map.html#layers layers} in the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#map map}.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#popup Read more...}
     */
    popup?: PopupProperties | nullish;
    /**
     * Controls whether the popup opens when users click on the view.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#popupEnabled Read more...}
     */
    popupEnabled?: PopupViewProperties["popupEnabled"];
    /**
     * SceneView can draw scenes in three different quality modes: `high`, `medium` and `low`.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#qualityProfile Read more...}
     */
    qualityProfile?: "low" | "medium" | "high";
    /**
     * Represents an approximation of the map scale.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#scale Read more...}
     */
    scale?: number;
    /**
     * Exposes the default widgets available in the view and allows you to toggle them on
     * and off.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#ui Read more...}
     */
    ui?: DefaultUIProperties;
    /**
     * The viewing mode (`local` or `global`).
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#viewingMode Read more...}
     */
    viewingMode?: "global" | "local";
    /**
     * Represents the current view as a {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-Viewpoint.html Viewpoint}
     * or point of observation on the view.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#viewpoint Read more...}
     */
    viewpoint?: ViewpointProperties;
    /**
     * A convenience property indicating the general size of the view's width.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#widthBreakpoint Read more...}
     */
    widthBreakpoint?: BreakpointsOwnerProperties["widthBreakpoint"];
    /**
     * Represents the level of detail (LOD) at the center of the view.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#zoom Read more...}
     */
    zoom?: number;
  }

  export type EasingFunction = (t: number, duration: number) => number;

  /**
   * Animation options for the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#goTo goTo()} method.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#GoToOptions3D Read more...}
   */
  export interface GoToOptions3D {
    animate?: boolean;
    speedFactor?: number;
    duration?: number;
    maxDuration?: number;
    easing?: | "linear"
    | "cubic-in"
    | "cubic-out"
    | "cubic-in-out"
    | "expo-in"
    | "expo-out"
    | "expo-in-out"
    | "quad-in-out-coast"
    | "in-cubic"
    | "out-cubic"
    | "in-out-cubic"
    | "in-expo"
    | "out-expo"
    | "in-out-expo"
    | "in-out-coast-quad"
    | "ease"
    | "ease-in"
    | "ease-out"
    | "ease-in-out"
    | EasingFunction;
    signal?: AbortSignal | nullish;
  }

  /**
   * The target location/viewpoint to animate to in the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#goTo goTo()} method.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#GoToTarget3D Read more...}
   */
  export type GoToTarget3D = | number[]
    | GeometryUnion
    | GeometryUnion[]
    | Collection<GeometryUnion>
    | Graphic
    | Graphic[]
    | Collection<Graphic>
    | Camera
    | Viewpoint
    | any;

  /**
   * Object specification for the graphic hit result returned in {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#HitTestResult HitTestResult} of the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#hitTest hitTest()} method.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#GraphicHit Read more...}
   */
  export interface GraphicHit {
    type: "graphic";
    graphic: Graphic;
    distance: number;
    layer: Layer | nullish;
    mapPoint: Point | nullish;
  }

  /**
   * Object specification for the result of the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#hitTest hitTest()} method.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#HitTestResult Read more...}
   */
  export interface SceneViewHitTestResult {
    results: ViewHit[];
    ground: HitTestResultGround;
    screenPoint: SceneViewScreenPoint | MouseEvent;
  }

  /**
   * A layer or graphic to be used in {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#toMap toMap} and {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#hitTest hitTest} filter options.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#IntersectItem Read more...}
   */
  export type IntersectItem = Graphic | Layer | BuildingSublayer | SubtypeSublayer | Ground;

  /**
   * Object specification for the media hit results returned from {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-MediaLayer.html MediaLayer} in {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#HitTestResult HitTestResult} of the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#hitTest hitTest()} method.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#MediaHit Read more...}
   */
  export interface MediaHit {
    type: "media";
    element: ImageElement | VideoElement;
    distance: number;
    layer: MediaLayer;
    mapPoint: Point | nullish;
    sourcePoint: SourcePoint | nullish;
  }

  /**
   * Object specification for the route hit results returned from {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-RouteLayer.html RouteLayer} in {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#HitTestResult HitTestResult} of the {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#hitTest hitTest()} method.
   *
   * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-views-SceneView.html#RouteHit Read more...}
   */
  export interface RouteHit {
    type: "route";
    layer: RouteLayer;
    mapPoint: Point;
    networkFeature: DirectionLine | DirectionPoint | PointBarrier | PolygonBarrier | PolylineBarrier | RouteInfo | Stop;
  }

