    /**
     * The associated {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-catalog-CatalogFootprintLayer.html CatalogFootprintLayer}, {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-CSVLayer.html CSVLayer}, {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-FeatureLayer.html FeatureLayer}, {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-GeoJSONLayer.html GeoJSONLayer}, {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-ImageryLayer.html ImageryLayer},
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-knowledgeGraph-KnowledgeGraphSublayer.html KnowledgeGraphSublayer}, {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-SceneLayer.html SceneLayer}, or {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-layers-WFSLayer.html WFSLayer} containing the fields and attributes to display within the widget.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-widgets-FeatureTable-AttachmentsColumn.html#layer Read more...}
     */
    layer: | CatalogFootprintLayer
      | CSVLayer
      | FeatureLayer
      | GeoJSONLayer
      | ImageryLayer
      | KnowledgeGraphSublayer
      | SceneLayer
      | WFSLayer
      | nullish;
    /**
     * Indicates whether the attachments column is sortable.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-widgets-FeatureTable-AttachmentsColumn.html#sortable Read more...}
     */
    readonly sortable: boolean;
    /**
     * The text alignment of the attachments column.
     *
     * {@link https://developers.arcgis.com/javascript/latest/api-reference/esri-widgets-FeatureTable-AttachmentsColumn.html#textAlign Read more...}
     */
